class WebError(BaseModel):
    """A serializable failure carried by a WebBase -- never a bare Exception
    on the wire."""

    type: str
    message: str
    detail: dict[str, Any] = {}

    @classmethod
    def from_exception(cls, exc: BaseException) -> WebError:
        return cls(type=type(exc).__name__, message=str(exc))


class WebBase(BaseModel):
    """Addressable, error-carrying base of every surface object. Names/roots
    are assigned by the resolver that registers the object (Decision 9)."""

    name: str = ""                  # short, low-entropy: doc:000-001
    kind: str = ""
    root: str | None = None         # name of the object this derives from
    created: int = 0
    updated: int = 0
    accessed: int = 0
    error: WebError | None = None
    message: str | None = None
    ok: bool = True                 # the ONLY truth; `error` is diagnostics

    _registrable: ClassVar[bool] = True
    _client: Any = PrivateAttr(default=None)        # owning WebClient
    _session: Any = PrivateAttr(default=None)
    _fields: dict[str, Any] = PrivateAttr(default_factory=dict)

    if not TYPE_CHECKING:
        def __getattr__(self, name: str) -> Any:
            """Ops live in ``core.ops``, not on this data class (PLAN §9): a
            bare eager call (e.g. on a collected Document) is dispatched to the
            registry. ``_``-names and model fields are pydantic's; an
            unregistered name raises as usual."""
            if name.startswith("_"):
                return super().__getattr__(name)
            from .ops import CALL_OPS, PROP_OPS, _lookup, read_prop, run_op
            if _lookup(PROP_OPS, self, name) is not None:
                return read_prop(self, name)
            if _lookup(CALL_OPS, self, name) is not None:
                return lambda *a, **k: run_op(self, name, list(a), k)
            return super().__getattr__(name)

    # -- extraction / accessors ----------------------------------------------
    # Every op (extract/project/field/reference(s)/document(s)/is_ok/is_empty)
    # lives in ``core.ops`` (PLAN §9); WebBase is data + the ``__getattr__``
    # dispatch above. Typed eager signatures are generated into the block below.
    if TYPE_CHECKING:
        # >>> eager:WebBase generated by scripts/gen_stubs.py -- do not edit
        def document(self, name: str, *, error: ErrorPolicy | None = None) -> Document: ...  # type: ignore[empty-body]
        def documents(self, *names: str, error: ErrorPolicy | None = None) -> Collection[Document]: ...  # type: ignore[empty-body]
