        def check(self, selector: str, checked: bool = True, *, error: ErrorPolicy | None = None, **kw: Any) -> Collection[Document]: ...  # type: ignore[empty-body]
        def click(self, selector: str | None = None, *, error: ErrorPolicy | None = None, **kw: Any) -> Collection[Document]: ...  # type: ignore[empty-body]
        def document(self, name: str, *, error: ErrorPolicy | None = None) -> Collection[Document]: ...  # type: ignore[empty-body]
